DROP TABLE IF EXISTS `gameanalyses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `gameanalyses` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `GameId` int NOT NULL,
  `AccuracyRed` int NOT NULL,
  `AccuracyBlack` int NOT NULL,
  `TurningPointMoveOrder` int DEFAULT NULL,
  `BrilliantCount` int NOT NULL,
  `BestCount` int NOT NULL,
  `GoodCount` int NOT NULL,
  `InaccuracyCount` int NOT NULL,
  `BlunderCount` int NOT NULL,
  `SummaryReviewJson` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `AnalyzedAt` datetime(6) NOT NULL,
  PRIMARY KEY (`Id`),
  UNIQUE KEY `IX_GameAnalyses_GameId` (`GameId`),
  CONSTRAINT `FK_GameAnalyses_Games_GameId` FOREIGN KEY (`GameId`) REFERENCES `games` (`Id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
