DROP TABLE IF EXISTS `games`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `games` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `Status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `CurrentTurn` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `CreatedAt` datetime(6) NOT NULL,
  `LastMoveAt` datetime(6) DEFAULT NULL,
  `BlackPlayerId` int DEFAULT NULL,
  `GameType` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `RedPlayerId` int DEFAULT NULL,
  `Winner` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `RoomCode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `InitialFen` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `AiDepth` int DEFAULT NULL,
  `GameMode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'PvP',
  `OpeningId` int DEFAULT NULL,
  `IsRated` tinyint(1) NOT NULL DEFAULT '0',
  `ResultsProcessedAt` datetime(6) DEFAULT NULL,
  `TimeControlMinutes` int NOT NULL DEFAULT '3',
  `Version` bigint NOT NULL DEFAULT '0',
  `AiColor` varchar(10) DEFAULT 'Black',
  PRIMARY KEY (`Id`),
  UNIQUE KEY `IX_Games_RoomCode` (`RoomCode`),
  KEY `IX_Games_BlackPlayerId` (`BlackPlayerId`),
  KEY `IX_Games_RedPlayerId` (`RedPlayerId`),
  KEY `IX_Games_OpeningId` (`OpeningId`),
  KEY `IX_Games_GameMode_Status` (`GameMode`,`Status`),
  CONSTRAINT `FK_Games_Openings_OpeningId` FOREIGN KEY (`OpeningId`) REFERENCES `openings` (`Id`) ON DELETE SET NULL,
  CONSTRAINT `FK_Games_Users_BlackPlayerId` FOREIGN KEY (`BlackPlayerId`) REFERENCES `users` (`Id`) ON DELETE SET NULL,
  CONSTRAINT `FK_Games_Users_RedPlayerId` FOREIGN KEY (`RedPlayerId`) REFERENCES `users` (`Id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=211 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
