DROP TABLE IF EXISTS `moves`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `moves` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `GameId` int NOT NULL,
  `FromX` int NOT NULL,
  `FromY` int NOT NULL,
  `ToX` int NOT NULL,
  `ToY` int NOT NULL,
  `PieceType` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `PieceColor` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `MoveOrder` int NOT NULL,
  `MovedAt` datetime(6) NOT NULL,
  `BestAlternative` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `EvalScore` int DEFAULT NULL,
  `Judgment` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `WinRate` float DEFAULT NULL,
  PRIMARY KEY (`Id`),
  UNIQUE KEY `IX_Moves_GameId_MoveOrder` (`GameId`,`MoveOrder`),
  KEY `IX_Moves_GameId` (`GameId`),
  CONSTRAINT `FK_Moves_Games_GameId` FOREIGN KEY (`GameId`) REFERENCES `games` (`Id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1727 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
