INSERT INTO `openingbookmoves` VALUES (1,1,'rnbakabnr/9/1c5c1/p1p1p1p1p/9/9/P1P1P1P1P/1C5C1/9/RNBAKABNR w - - 0 1','Pháo 2 bình 5 (C2.5)',1,12500,8900,7600,58.4,'Pháo vào giữa kiểm soát lộ trung tâm, sẵn sàng bắn Tốt đầu uy hiếp Tướng.'),(2,1,'rnbakabnr/9/1c5c1/p1p1p1p1p/9/9/P1P1P1P1P/4C1C2/9/RNBAKABNR b - - 1 1','Mã 8 tiến 7 (M8.7)',2,9800,7200,6500,52.1,'Bên Đen nhảy Mã bảo vệ Tốt đầu, hình thành thế trận Bình Phong Mã đối kháng.'),(3,2,'rnbakabnr/9/1c5c1/p1p1p1p1p/9/9/P1P1P1P1P/4C1C2/9/RNBAKABNR b - - 1 1','Mã 2 tiến 3 (M2.3)',2,8400,6100,5900,51.5,'Mã cánh phải phát triển kiểm soát trung lộ và bảo vệ Tốt đầu.'),(4,3,'rnbakabnr/9/1c5c1/p1p1p1p1p/9/9/P1P1P1P1P/4C1C2/9/RNBAKABNR b - - 1 1','Pháo 8 bình 5 (C8.5)',2,7100,4500,6900,49.8,'Đen cũng đưa Pháo vào giữa, tạo thế Thuận Pháo đối công trực diện.'),(5,4,'rnbakabnr/9/1c5c1/p1p1p1p1p/9/9/P1P1P1P1P/1C5C1/9/RNBAKABNR w - - 0 1','Tốt 7 tiến 1 (B7.1)',1,11200,9400,7800,54.2,'Tiến Tốt mở đường cho Mã phát triển và thăm dò phản ứng của đối phương.');
